/* ── element spec (one line per drawn element) ─────────────────────────────
   x / y / z axis   → Cylinder shaft r=0.015 + Cone head (0.08,0.28), black
   origin O         → label only
   r vector         → Cylinder shaft r=0.060 + Cone head (0.17,0.50), navy #1F3A66
   P                → SphereGeometry(0.09) black + italic label
   F vector         → Cylinder shaft r=0.048 + Cone head (0.15,0.45), red #C8342C
   tau vector       → Cylinder shaft r=0.048 + Cone head (0.15,0.45), orange #F5A11E
   line of action   → Line + LineDashedMaterial, black 60%
   r extension      → Line + LineDashedMaterial, black 60%
   theta arc (near) → Line, radius 0.70 at P, black
   theta arc (far)  → Line, radius 0.90 at P, black
   r_perp           → thin Line O -> foot, black
   right-angle mark → 3-point polyline, 0.22 units, black
   hand overlay     → Box palm + Cylinder/Sphere fingers & thumb (Lambert, skin)
   overlay r / F    → duplicate arrows (navy / red)
   curl arrows      → TorusGeometry arcs (0.5, 0.025) + Cone heads, black
   ───────────────────────────────────────────────────────────────────────── */

const NAVY = 0x1F3A66, RED = 0xC8342C, ORANGE = 0xF5A11E, BLACK = 0x000000;
const SKIN = 0xF2C9A0, SKIN_D = 0xD9A77C;

// figure coords (x toward viewer, y right, z up)  ->  world (y-up)
const fv = (fx, fy, fz) => new THREE.Vector3(fy, fz, fx);
const UP = new THREE.Vector3(0, 1, 0);
const ORIGIN = new THREE.Vector3(0, 0, 0);

const P = fv(1.4, 3.2, 0);              // point of application
const R_LEN = P.length();               // ~3.49
const R_HAT = P.clone().normalize();
const F_LEN = 2.2;
const TAU_SCALE = 0.45;

/* lights (only the hand uses shaded material) */
scene.add(new THREE.AmbientLight(0xffffff, 0.85));
const _dl = new THREE.DirectionalLight(0xffffff, 0.55);
_dl.position.set(5, 9, 7);
scene.add(_dl);

/* ── arrow factory ─────────────────────────────────────────────────────── */
function makeArrow(parent, color, shaftR, headR, headL) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 20), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 24), mat);
  const g = new THREE.Group();
  g.add(shaft); g.add(head);
  parent.add(g);
  const api = {
    group: g, mat, shaft, head, baseColor: new THREE.Color(color),
    set(origin, dir, len) {
      if (!(len > headL * 1.02)) { g.visible = false; return api; }
      g.visible = true;
      g.position.copy(origin);
      g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
      const sl = len - headL;
      shaft.scale.set(1, sl, 1);
      shaft.position.set(0, sl / 2, 0);
      head.position.set(0, len - headL / 2, 0);
      return api;
    }
  };
  return api;
}

function makeDashed(parent) {
  const mat = new THREE.LineDashedMaterial({
    color: BLACK, dashSize: 0.20, gapSize: 0.13, transparent: true, opacity: 0.6
  });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  parent.add(line);
  return {
    line,
    set(a, b) {
      const g = new THREE.BufferGeometry().setFromPoints([a, b]);
      line.geometry.dispose();
      line.geometry = g;
      line.computeLineDistances();
    }
  };
}

function makePolyline(parent, color, opacity = 1) {
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  parent.add(line);
  return {
    line,
    set(pts) {
      const g = new THREE.BufferGeometry().setFromPoints(pts);
      line.geometry.dispose();
      line.geometry = g;
    }
  };
}

function arcPoints(center, A, B, radius, n = 60) {
  const a = A.clone().normalize(), b = B.clone().normalize();
  let axis = new THREE.Vector3().crossVectors(a, b);
  const ang = Math.acos(THREE.MathUtils.clamp(a.dot(b), -1, 1));
  if (axis.lengthSq() < 1e-8) axis.copy(UP); else axis.normalize();
  const pts = [];
  for (let i = 0; i <= n; i++) {
    pts.push(a.clone().applyAxisAngle(axis, ang * (i / n)).multiplyScalar(radius).add(center));
  }
  return pts;
}

/* ── axes ──────────────────────────────────────────────────────────────── */
const axisGroup = new THREE.Group(); scene.add(axisGroup);
makeArrow(axisGroup, BLACK, 0.015, 0.08, 0.28).set(ORIGIN, fv(0, 1, 0), 6.0); // y
makeArrow(axisGroup, BLACK, 0.015, 0.08, 0.28).set(ORIGIN, fv(0, 0, 1), 5.0); // z
makeArrow(axisGroup, BLACK, 0.015, 0.08, 0.28).set(ORIGIN, fv(1, 0, 0), 5.0); // x

/* ── main vectors ──────────────────────────────────────────────────────── */
const arrR = makeArrow(scene, NAVY, 0.060, 0.17, 0.50).set(ORIGIN, R_HAT, R_LEN);
const arrF = makeArrow(scene, RED, 0.048, 0.15, 0.45);
const arrTau = makeArrow(scene, ORANGE, 0.048, 0.15, 0.45);

const dotP = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 16),
  new THREE.MeshBasicMaterial({ color: BLACK }));
dotP.position.copy(P);
scene.add(dotP);

/* ── geometric construction group ──────────────────────────────────────── */
const consGroup = new THREE.Group(); scene.add(consGroup);
const dashAction = makeDashed(consGroup);
const dashRext = makeDashed(consGroup);
const arcNear = makePolyline(consGroup, BLACK);
const arcFar = makePolyline(consGroup, BLACK);
const perpLine = makePolyline(consGroup, BLACK);
const sqMark = makePolyline(consGroup, BLACK);

/* ── right-hand overlay ────────────────────────────────────────────────── */
const handGroup = new THREE.Group();
scene.add(handGroup);
{
  const e1 = R_HAT.clone();
  const e2 = UP.clone();
  const e3 = new THREE.Vector3().crossVectors(e1, e2).normalize();
  const m = new THREE.Matrix4().makeBasis(e1, e2, e3);
  handGroup.quaternion.setFromRotationMatrix(m);
  handGroup.position.copy(fv(4.3, 0.55, -1.7));
}
const skinMat = new THREE.MeshLambertMaterial({ color: SKIN });

function limbX(len, rad) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rad, rad * 0.88, len, 12), skinMat);
  mesh.rotation.z = -Math.PI / 2;
  mesh.position.x = len / 2;
  return mesh;
}
function makeFinger(baseX, y, len, rad, bend) {
  const g = new THREE.Group();
  g.position.set(baseX, y, 0);
  g.add(limbX(len * 0.6, rad));
  const knuck = new THREE.Mesh(new THREE.SphereGeometry(rad * 1.05, 10, 8), skinMat);
  knuck.position.x = len * 0.6; g.add(knuck);
  const g2 = new THREE.Group();
  g2.position.x = len * 0.6; g2.rotation.y = bend;
  g2.add(limbX(len * 0.45, rad * 0.92));
  const tip = new THREE.Mesh(new THREE.SphereGeometry(rad * 0.85, 10, 8), skinMat);
  tip.position.x = len * 0.45; g2.add(tip);
  g.add(g2);
  return g;
}
{
  const palm = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.85, 0.20), skinMat);
  palm.position.set(0.48, 0, 0);
  handGroup.add(palm);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(palm.geometry),
    new THREE.LineBasicMaterial({ color: SKIN_D }));
  edges.position.copy(palm.position);
  handGroup.add(edges);

  const wrist = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.24, 0.5, 14), skinMat);
  wrist.rotation.z = Math.PI / 2; wrist.position.set(-0.24, 0, 0);
  handGroup.add(wrist);

  handGroup.add(makeFinger(0.95, 0.31, 0.62, 0.072, 0.45));
  handGroup.add(makeFinger(0.97, 0.10, 0.68, 0.072, 0.50));
  handGroup.add(makeFinger(0.95, -0.11, 0.64, 0.068, 0.55));
  handGroup.add(makeFinger(0.90, -0.31, 0.52, 0.062, 0.60));

  const thumb = new THREE.Group();
  thumb.position.set(0.26, 0.40, 0.02);
  thumb.rotation.z = -0.25;
  const tSeg = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.075, 0.48, 12), skinMat);
  tSeg.position.y = 0.24; thumb.add(tSeg);
  const tTip = new THREE.Mesh(new THREE.SphereGeometry(0.078, 10, 8), skinMat);
  tTip.position.y = 0.48; thumb.add(tTip);
  handGroup.add(thumb);
}
const arrRo = makeArrow(handGroup, NAVY, 0.055, 0.16, 0.46);
const arrFo = makeArrow(handGroup, RED, 0.045, 0.14, 0.42);
arrRo.set(new THREE.Vector3(0.95, 0, 0), new THREE.Vector3(1, 0, 0), 3.0);

const curlMat = new THREE.MeshBasicMaterial({ color: BLACK });
function makeCurl(cx, cy, radius, sweep) {
  const g = new THREE.Group();
  const torus = new THREE.Mesh(new THREE.TorusGeometry(radius, 0.026, 8, 40, sweep), curlMat);
  torus.rotation.x = -Math.PI / 2;
  g.add(torus);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.21, 16), curlMat);
  const pEnd = new THREE.Vector3(Math.cos(sweep) * radius, 0, -Math.sin(sweep) * radius);
  const tan = new THREE.Vector3(-Math.sin(sweep), 0, -Math.cos(sweep)).normalize();
  head.position.copy(pEnd);
  head.quaternion.setFromUnitVectors(UP, tan);
  g.add(head);
  g.position.set(cx, cy, 0);
  return g;
}
handGroup.add(makeCurl(1.55, 0.36, 0.50, 2.1));
handGroup.add(makeCurl(2.85, -0.34, 0.46, 2.1));

/* ── live update ───────────────────────────────────────────────────────── */
let theta = 35;
let Fdir = R_HAT.clone();
let perpLen = 0, tauLen = 0;

const lbl = {};
function setLbl(key, v) { if (lbl[key]) lbl[key].pos.copy(v); }

function update() {
  const th = THREE.MathUtils.degToRad(theta);
  Fdir = R_HAT.clone().applyAxisAngle(UP, th);

  arrF.set(P, Fdir, F_LEN);
  tauLen = TAU_SCALE * R_LEN * F_LEN * Math.sin(th);
  arrTau.set(P, UP, tauLen);

  dashAction.set(P.clone().addScaledVector(Fdir, -3.5), P.clone().addScaledVector(Fdir, 3.5));
  dashRext.set(P.clone().addScaledVector(R_HAT, -0.06), P.clone().addScaledVector(R_HAT, 1.5));

  // perpendicular from O onto the line of action
  const t = -P.dot(Fdir);
  const foot = P.clone().addScaledVector(Fdir, t);
  perpLen = foot.length();
  const showPerp = perpLen > 0.14;
  perpLine.line.visible = showPerp;
  sqMark.line.visible = showPerp;
  if (showPerp) {
    perpLine.set([ORIGIN.clone(), foot.clone()]);
    const s = 0.22;
    const u = Fdir.clone().multiplyScalar(t > 0 ? -1 : 1);
    const v = foot.clone().negate().normalize();
    sqMark.set([
      foot.clone().addScaledVector(u, s),
      foot.clone().addScaledVector(u, s).addScaledVector(v, s),
      foot.clone().addScaledVector(v, s)
    ]);
    setLbl('rperp', foot.clone().multiplyScalar(0.55).addScaledVector(u, 0.12));
  }

  const showArc = theta > 4 && theta < 176;
  arcNear.line.visible = showArc;
  arcFar.line.visible = showArc;
  if (showArc) {
    const nA = Fdir.clone().negate(), nB = R_HAT.clone().negate();
    arcNear.set(arcPoints(P, nA, nB, 0.70));
    arcFar.set(arcPoints(P, Fdir, R_HAT, 0.90));
    setLbl('th1', P.clone().addScaledVector(nA.clone().add(nB).normalize(), 0.95));
    setLbl('th2', P.clone().addScaledVector(Fdir.clone().add(R_HAT).normalize(), 1.18));
  }

  // overlay F (local frame: +X = r, +Y = tau, fingers curl toward -Z)
  arrFo.set(new THREE.Vector3(1.45, 0.62, 0),
    new THREE.Vector3(Math.cos(th), 0, -Math.sin(th)), F_LEN);

  // labels that follow the geometry
  setLbl('F', P.clone().addScaledVector(Fdir, F_LEN + 0.45));
  setLbl('tau', P.clone().addScaledVector(UP, Math.max(tauLen, 0.15) + 0.35));
  if (lbl.th1) lbl.th1.div.style.visibility = showArc ? 'visible' : 'hidden';
  if (lbl.th2) lbl.th2.div.style.visibility = showArc ? 'visible' : 'hidden';
  if (lbl.rperp) lbl.rperp.div.style.visibility =
    (showPerp && mode === 'geo') ? 'visible' : 'hidden';
  if (lbl.tau) lbl.tau.div.style.visibility = tauLen > 0.5 ? 'visible' : 'hidden';

  const oF = new THREE.Vector3(1.45, 0.62, 0)
    .addScaledVector(new THREE.Vector3(Math.cos(th), 0, -Math.sin(th)), F_LEN + 0.4);
  if (lbl.oF) lbl.oF.pos.copy(handGroup.localToWorld(oF.clone()));

  // panel readout
  const sv = Math.sin(th);
  document.getElementById('thetaVal').textContent = theta.toFixed(0) + '\u00B0';
  document.getElementById('readout').innerHTML =
    '|r| = ' + R_LEN.toFixed(2) + '&nbsp;&nbsp;|F| = ' + F_LEN.toFixed(2) + '<br>' +
    'r&#8869; = |r| sin&theta; = ' + (R_LEN * sv).toFixed(2) + '<br>' +
    '|&tau;| = |r||F| sin&theta; = ' + (R_LEN * F_LEN * sv).toFixed(2);
}

/* ── mode ──────────────────────────────────────────────────────────────── */
let mode = 'geo';
function setMode(m) {
  mode = m;
  consGroup.visible = (m === 'geo');
  handGroup.visible = (m === 'hand');
  document.getElementById('modeGeo').classList.toggle('active', m === 'geo');
  document.getElementById('modeHand').classList.toggle('active', m === 'hand');
  ['th1', 'th2', 'rperp'].forEach(k => {
    if (lbl[k]) lbl[k].div.style.visibility = (m === 'geo') ? 'visible' : 'hidden';
  });
  ['oR', 'oF'].forEach(k => {
    if (lbl[k]) lbl[k].div.style.visibility = (m === 'hand') ? 'visible' : 'hidden';
  });
  update();
}

update();
handGroup.visible = true;   // keep in bounds for the auto-fit below

/* ── camera ────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.62
});
controls.minPolarAngle = 0.06;
controls.maxPolarAngle = Math.PI * 0.62;

/* ── labels ────────────────────────────────────────────────────────────── */
const VEC = '14px', AX = '13px';
addLabel('<i><b>y</b></i>', fv(0, 6.0, 0), { fontSize: AX, offset: [10, 10] });
addLabel('<i><b>z</b></i>', fv(0, 0, 5.0), { fontSize: AX, offset: [-10, -10] });
addLabel('<i><b>x</b></i>', fv(5.0, 0, 0), { fontSize: AX, offset: [-2, 16] });
addLabel('O', ORIGIN, { fontSize: AX, offset: [-14, -8] });
addLabel('<i>P</i>', P, { fontSize: AX, offset: [2, 16] });
addLabel('<b><i>r</i>&#8407;</b>', P.clone().multiplyScalar(0.62),
  { fontSize: VEC, color: '#111', offset: [6, -16] });

lbl.F = addLabel('<b><i>F</i>&#8407;</b>', P.clone().addScaledVector(Fdir, F_LEN + 0.45),
  { fontSize: VEC, offset: [18, -4] });
lbl.tau = addLabel('<b>&tau;&#8407;</b>', P.clone().addScaledVector(UP, tauLen + 0.35),
  { fontSize: VEC, offset: [16, -4] });
lbl.th1 = addLabel('&theta;', P.clone(), { fontSize: AX });
lbl.th2 = addLabel('&theta;', P.clone(), { fontSize: AX });
lbl.rperp = addLabel('<i>r</i><sub>&#8869;</sub>', ORIGIN.clone(), { fontSize: AX, offset: [-14, -6] });

lbl.oR = addLabel('<b><i>r</i>&#8407;</b>',
  handGroup.localToWorld(new THREE.Vector3(4.2, 0, 0)), { fontSize: VEC, offset: [10, 12] });
lbl.oF = addLabel('<b><i>F</i>&#8407;</b>',
  handGroup.localToWorld(new THREE.Vector3(3.9, 0.62, 0)), { fontSize: VEC, offset: [18, -4] });

/* ── interactive explanations ──────────────────────────────────────────── */
registerInteractive(arrR.group, {
  title: 'Position vector r',
  tooltip: 'r: from O to the point of application P',
  body: 'r points from the origin O to P, the point where the force acts. Only the component of r perpendicular to the line of action — the moment arm r⊥ = |r| sin θ — contributes to the torque.'
});
registerInteractive(arrF.group, {
  title: 'Force F',
  tooltip: 'F: applied force at P (drag the θ slider)',
  body: 'F acts at P in the same plane as r. The angle θ between r and F controls the torque: τ = |r||F| sin θ. Sliding θ to 0° or 180° aligns F with the line through O and kills the torque.'
});
registerInteractive(arrTau.group, {
  title: 'Torque τ = r × F',
  tooltip: 'τ: perpendicular to the plane of r and F',
  body: 'τ = r × F stands perpendicular to the plane containing r and F, here along +z. Its length |r||F| sin θ is largest at θ = 90° and zero when r and F are parallel or antiparallel. Orbit the scene to see that it really leaves the r–F plane.'
});
registerInteractive(perpLine.line, {
  title: 'Moment arm r⊥',
  tooltip: 'r⊥: perpendicular distance from O to the line of action',
  body: 'r⊥ is the perpendicular dropped from O onto the dashed line of action of F. Since |τ| = r⊥|F| = |r||F| sin θ, the torque is the force times this moment arm.'
});
registerInteractive(handGroup, {
  title: 'Right-hand rule',
  tooltip: 'Fingers along r, curl toward F, thumb gives τ',
  body: 'Point the fingers of your right hand along r, curl them toward F through the angle θ, and your thumb points along r × F — here straight up the +z axis, matching the orange τ arrow.'
});

/* ── controls wiring ───────────────────────────────────────────────────── */
const slider = document.getElementById('thetaAngle');
slider.addEventListener('input', () => {
  tween = null; playing = false;
  document.getElementById('btnPlay').textContent = 'Play';
  theta = parseFloat(slider.value);
  update();
});
document.getElementById('modeGeo').addEventListener('click', () => setMode('geo'));
document.getElementById('modeHand').addEventListener('click', () => setMode('hand'));

/* ── guided demo ───────────────────────────────────────────────────────── */
const steps = [
  { title: 'Torque at an oblique angle', narration: 'The force F acts at P, a distance r from the origin. The perpendicular distance r⊥ from O to the line of action sets the moment arm, and τ points straight up along +z.', theta: 35, mode: 'geo' },
  { title: 'Maximum torque at 90°', narration: 'Rotating F until it is perpendicular to r makes r⊥ equal to the full length of r; the orange τ arrow reaches its longest.', theta: 90, mode: 'geo' },
  { title: 'Zero torque when aligned', narration: 'With F along the line of r, the line of action passes through O, r⊥ shrinks to zero and the τ arrow vanishes.', theta: 2, mode: 'geo' },
  { title: 'Right-hand rule fixes the direction', narration: 'Switching to the hand overlay: fingers curl from r toward F and the thumb points along +z, matching the orange τ arrow.', theta: 55, mode: 'hand' }
];
let stepIndex = 0, tween = null, playing = false, dwell = 0;

function goToStep(i) {
  stepIndex = (i + steps.length) % steps.length;
  const s = steps[stepIndex];
  setMode(s.mode);
  tween = { from: theta, to: s.theta, t: 0 };
  document.getElementById('stepTitle').textContent = (stepIndex + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narration;
  dwell = 0;
}
document.getElementById('btnPrev').addEventListener('click', () => { playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIndex - 1); });
document.getElementById('btnNext').addEventListener('click', () => { playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIndex + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.textContent = playing ? 'Pause' : 'Play';
  if (playing) goToStep(stepIndex);
});
goToStep(0);

/* ── own animation loop (tween + pulse highlight) ──────────────────────── */
const C_BLACK = new THREE.Color(BLACK), C_ORANGE = new THREE.Color(ORANGE),
  C_GLOW = new THREE.Color(0xFFD27A);
let _t0 = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - _t0) / 1000); _t0 = now;

  if (tween) {
    tween.t = Math.min(1, tween.t + dt / 0.9);
    const k = tween.t * tween.t * (3 - 2 * tween.t);
    theta = tween.from + (tween.to - tween.from) * k;
    slider.value = theta.toFixed(0);
    update();
    if (tween.t >= 1) { theta = tween.to; tween = null; }
  } else if (playing) {
    dwell += dt;
    if (dwell > 3.0) goToStep(stepIndex + 1);
  }

  if (mode === 'hand') {
    const k = 0.5 + 0.5 * Math.sin(now * 0.004);
    curlMat.color.copy(C_BLACK).lerp(C_ORANGE, 0.75 * k);
    arrTau.mat.color.copy(C_ORANGE).lerp(C_GLOW, k);
  } else {
    curlMat.color.copy(C_BLACK);
    arrTau.mat.color.copy(C_ORANGE);
  }
}
requestAnimationFrame(tick);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

