    const c2 = c1.clone().addScaledVector(v, s);
    const c3 = foot.clone().addScaledVector(v, s);
    sqA.set([c1, c2]);
    sqB.set([c2, c3]);
    setLbl('rperp', foot.clone().multiplyScalar(0.5).addScaledVector(u, 0.20));
  }
  showLbl('rperp', showPerp);

  const showArc = theta > 5 && theta < 175;
  arcNear.mesh.visible = showArc;
  arcFar.mesh.visible = showArc;
  if (showArc) {
    const nA = Fdir.clone().negate(), nB = R_HAT.clone().negate();
    arcNear.set(arcPoints(P, nA, nB, 0.70));
    arcFar.set(arcPoints(P, Fdir, R_HAT, 0.90));
    setLbl('th1', P.clone().addScaledVector(nA.clone().add(nB).normalize(), 0.95));
    setLbl('th2', P.clone().addScaledVector(Fdir.clone().add(R_HAT).normalize(), 1.20));
  }
  showLbl('th1', showArc);
  showLbl('th2', showArc);

  // overlay F (local frame: +X = r, +Y = tau, fingers curl toward -Z)
  const oFdir = new THREE.Vector3(Math.cos(th), 0, -Math.sin(th));
  arrFo.set(OF_START, oFdir, F_LEN);

  // labels that follow the geometry
  setLbl('F', P.clone().addScaledVector(Fdir, F_LEN + 0.42));
  setLbl('tau', P.clone().addScaledVector(UP, Math.max(tauLen, 0.2) + 0.38));
  showLbl('tau', tauLen > 0.5);

  if (lbl.oF) {
    lbl.oF.pos.copy(handGroup.localToWorld(
      OF_START.clone().addScaledVector(oFdir, F_LEN + 0.38)));
  }

  // panel readout
  const sv = Math.sin(th);
  document.getElementById('thetaVal').textContent = theta.toFixed(0) + '\u00B0';
  document.getElementById('readout').innerHTML =
    '|r| = ' + R_LEN.toFixed(2) + '&nbsp;&nbsp;|F| = ' + F_LEN.toFixed(2) + '<br>' +
    'r&#8869; = |r| sin&theta; = ' + (R_LEN * sv).toFixed(2) + '<br>' +
    '|&tau;| = |r||F| sin&theta; = ' + (R_LEN * F_LEN * sv).toFixed(2);
}

/* ── emphasis mode (both overlays stay on screen, like the source) ─────── */
function setMode(m) {
  mode = m;
  const cOp = (m === 'geo') ? 1.0 : 0.30;
  consTubeMats.forEach(mt => { mt.opacity = cOp; });
  dashMats.forEach(mt => { mt.opacity = (m === 'geo') ? 0.85 : 0.25; });
  const hOp = (m === 'hand') ? 1.0 : 0.55;
  handMats.forEach(mt => { mt.opacity = hOp; });
  document.getElementById('modeGeo').classList.toggle('active', m === 'geo');
  document.getElementById('modeHand').classList.toggle('active', m === 'hand');
  ['th1', 'th2', 'rperp'].forEach(k => {
    if (lbl[k]) lbl[k].div.style.opacity = (m === 'geo') ? '1' : '0.35';
  });
  ['oR', 'oF'].forEach(k => {
    if (lbl[k]) lbl[k].div.style.opacity = (m === 'hand') ? '1' : '0.55';
