const TAU_SCALE = 0.45;

/* vector-symbol label helper (real arrow glyph, no combining marks) */
function vec(sym) {
  return '<span style="display:inline-block;position:relative;line-height:1;">' +
    '<span style="position:absolute;left:50%;top:-0.60em;transform:translateX(-50%);font-size:0.70em;">&#8594;</span>' +
    '<i><b>' + sym + '</b></i></span>';
}

/* lights (only the hand uses shaded material) */
scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const _dl = new THREE.DirectionalLight(0xffffff, 0.62);
_dl.position.set(5, 9, 7);
scene.add(_dl);
const _dl2 = new THREE.DirectionalLight(0xffffff, 0.25);
_dl2.position.set(-6, 3, -5);
scene.add(_dl2);

/* ── arrow factory ─────────────────────────────────────────────────────── */
function makeArrow(parent, color, shaftR, headR, headL) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 20), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 24), mat);
  const g = new THREE.Group();
  g.add(shaft); g.add(head);
  parent.add(g);
  const api = {
    group: g, mat, shaft, head,
    set(origin, dir, len) {
      if (!(len > headL * 1.02)) { g.visible = false; return api; }
      g.visible = true;
      g.position.copy(origin);
      g.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
      const sl = len - headL;
      shaft.scale.set(1, sl, 1);
      shaft.position.set(0, sl / 2, 0);
      head.position.set(0, len - headL / 2, 0);
      return api;
    }
  };
  return api;
}

function makeDashed(parent) {
  const mat = new THREE.LineDashedMaterial({
    color: BLACK, dashSize: 0.22, gapSize: 0.14, transparent: true, opacity: 0.85
  });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  parent.add(line);
  return {
    line, mat,
    set(a, b) {
      const g = new THREE.BufferGeometry().setFromPoints([a, b]);
      line.geometry.dispose();
      line.geometry = g;
      line.computeLineDistances();
    }
  };
}

/* thick, always-readable polylines built as tubes */
function makeTube(parent, color, radius) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const mesh = new THREE.Mesh(new THREE.BufferGeometry(), mat);
  parent.add(mesh);
  return {
    mesh, mat,
    set(pts) {
      if (!pts || pts.length < 2) { mesh.visible = false; return; }
      mesh.visible = true;
      const curve = new THREE.CatmullRomCurve3(pts);
      const g = new THREE.TubeGeometry(curve, Math.max(6, pts.length), radius, 8, false);
      mesh.geometry.dispose();
      mesh.geometry = g;
    }
  };
}

function arcPoints(center, A, B, radius, n = 34) {
  const a = A.clone().normalize(), b = B.clone().normalize();
  let axis = new THREE.Vector3().crossVectors(a, b);
  const ang = Math.acos(THREE.MathUtils.clamp(a.dot(b), -1, 1));
  if (axis.lengthSq() < 1e-8) axis.copy(UP); else axis.normalize();
  const pts = [];
  for (let i = 0; i <= n; i++) {
    pts.push(a.clone().applyAxisAngle(axis, ang * (i / n)).multiplyScalar(radius).add(center));
  }
  return pts;
}

/* ── axes ──────────────────────────────────────────────────────────────── */
const axisGroup = new THREE.Group(); scene.add(axisGroup);
makeArrow(axisGroup, BLACK, 0.018, 0.09, 0.30).set(ORIGIN, fv(0, 1, 0), 6.0); // y
