const dashRext = makeDashed(consGroup);
const arcNear = makeTube(consGroup, BLACK, 0.022);
const arcFar = makeTube(consGroup, BLACK, 0.022);
const perpTube = makeTube(consGroup, BLACK, 0.022);
const sqA = makeTube(consGroup, BLACK, 0.019);
const sqB = makeTube(consGroup, BLACK, 0.019);
const consTubeMats = [arcNear.mat, arcFar.mat, perpTube.mat, sqA.mat, sqB.mat];
const dashMats = [dashAction.mat, dashRext.mat];

/* ── right-hand overlay (always visible, like the source) ──────────────── */
const handGroup = new THREE.Group();
scene.add(handGroup);
const OR_START = new THREE.Vector3(1.78, 0, 0);      // just past the fingertips
const OF_START = new THREE.Vector3(1.78, 0.20, 0);
const OR_LEN = 2.70;
{
  // local frame: +X along r (fingers), +Y up = tau (thumb), palm faces -Z (curl side)
  const e1 = R_HAT.clone();
