const skinMat = new THREE.MeshLambertMaterial({ color: SKIN, transparent: true, opacity: 1 });

function capsuleX(len, rad) {
  const m = new THREE.Mesh(new THREE.CapsuleGeometry(rad, Math.max(0.02, len), 6, 14), skinMat);
  m.rotation.z = -Math.PI / 2;
  m.position.x = len / 2;
