  g.position.set(bx, by, 0);
  g.rotation.y = bend1;                 // +Y rotation bends toward -Z (curl side)
  const L1 = len * 0.56, L2 = len * 0.44;
  g.add(capsuleX(L1, rad));
  const j = new THREE.Group();
  j.position.x = L1;
  j.rotation.y = bend2;
  j.add(capsuleX(L2, rad * 0.88));
  g.add(j);
  return g;
}
{
