}

const arrRo = makeArrow(handGroup, NAVY, 0.058, 0.17, 0.48);
const arrFo = makeArrow(handGroup, RED, 0.047, 0.15, 0.43);
arrRo.set(OR_START, new THREE.Vector3(1, 0, 0), OR_LEN);

const curlMat = new THREE.MeshBasicMaterial({ color: BLACK, transparent: true, opacity: 1 });
function makeCurl(cx, cy, radius, sweep) {
  const g = new THREE.Group();
  const torus = new THREE.Mesh(new THREE.TorusGeometry(radius, 0.028, 8, 44, sweep), curlMat);
  torus.rotation.x = -Math.PI / 2;   // arc runs from +X toward -Z (the curl sense)
  g.add(torus);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.082, 0.23, 16), curlMat);
  const pEnd = new THREE.Vector3(Math.cos(sweep) * radius, 0, -Math.sin(sweep) * radius);
  const tan = new THREE.Vector3(-Math.sin(sweep), 0, -Math.cos(sweep)).normalize();
  head.position.copy(pEnd);
  head.quaternion.setFromUnitVectors(UP, tan);
  g.add(head);
  g.position.set(cx, cy, 0);
  return g;
}
const curl1 = makeCurl(1.62, 0.02, 0.42, 2.15);
const curl2 = makeCurl(2.92, 0.02, 0.40, 2.15);
handGroup.add(curl1); handGroup.add(curl2);

/* ── live update ───────────────────────────────────────────────────────── */
let theta = 35;
let Fdir = R_HAT.clone();
let mode = 'geo';
let tween = null, playing = false, dwell = 0, stepIndex = 0;

const lbl = {};
function setLbl(key, v) { if (lbl[key]) lbl[key].pos.copy(v); }
function showLbl(key, on) { if (lbl[key]) lbl[key].div.style.visibility = on ? 'visible' : 'hidden'; }

function update() {
  const th = THREE.MathUtils.degToRad(theta);
  Fdir = R_HAT.clone().applyAxisAngle(UP, th);

  arrF.set(P, Fdir, F_LEN);
  const tauLen = TAU_SCALE * R_LEN * F_LEN * Math.sin(th);
  arrTau.set(P, UP, tauLen);

  dashAction.set(P.clone().addScaledVector(Fdir, -3.4), P.clone().addScaledVector(Fdir, 3.5));
  dashRext.set(P.clone().addScaledVector(R_HAT, -0.06), P.clone().addScaledVector(R_HAT, 1.5));

  // perpendicular from O onto the line of action
  const t = -P.dot(Fdir);
  const foot = P.clone().addScaledVector(Fdir, t);
  const perpLen = foot.length();
  const showPerp = perpLen > 0.22;
  perpTube.mesh.visible = showPerp;
  sqA.mesh.visible = showPerp;
  sqB.mesh.visible = showPerp;
  if (showPerp) {
    perpTube.set([ORIGIN.clone(), foot.clone()]);
    const s = 0.24;
    const u = Fdir.clone().multiplyScalar(t > 0 ? -1 : 1);   // along the line, away from P
    const v = foot.clone().negate().normalize();             // back toward O
    const c1 = foot.clone().addScaledVector(u, s);
    const c2 = c1.clone().addScaledVector(v, s);
    const c3 = foot.clone().addScaledVector(v, s);
    sqA.set([c1, c2]);
    sqB.set([c2, c3]);
    // label sits clear of the segment, on its outer side, near the O end
    setLbl('rperp', foot.clone().multiplyScalar(0.46).addScaledVector(u, 0.42));
  }
  showLbl('rperp', showPerp);

  const showArc = theta > 5 && theta < 175;
  arcNear.mesh.visible = showArc;
  arcFar.mesh.visible = showArc;
  if (showArc) {
    const nA = Fdir.clone().negate(), nB = R_HAT.clone().negate();
    arcNear.set(arcPoints(P, nA, nB, 0.70));
    arcFar.set(arcPoints(P, Fdir, R_HAT, 0.90));
    setLbl('th1', P.clone().addScaledVector(nA.clone().add(nB).normalize(), 1.00));
    setLbl('th2', P.clone().addScaledVector(Fdir.clone().add(R_HAT).normalize(), 1.26));
  }
  showLbl('th1', showArc);
  showLbl('th2', showArc);

  // overlay F (local frame: +X = r, +Y = tau, curl runs toward -Z)
  const oFdir = new THREE.Vector3(Math.cos(th), 0, -Math.sin(th));
  arrFo.set(OF_START, oFdir, F_LEN);

  // labels that follow the geometry
  setLbl('F', P.clone().addScaledVector(Fdir, F_LEN + 0.46));
  setLbl('tau', P.clone().addScaledVector(UP, Math.max(tauLen, 0.2) + 0.40));
  showLbl('tau', tauLen > 0.5);

  if (lbl.oF) {
    lbl.oF.pos.copy(handGroup.localToWorld(
      OF_START.clone().addScaledVector(oFdir, F_LEN + 0.44)));
  }

  // panel readout
  const sv = Math.sin(th);
  document.getElementById('thetaVal').textContent = theta.toFixed(0) + '\u00B0';
  document.getElementById('readout').innerHTML =
    '|r| = ' + R_LEN.toFixed(2) + '&nbsp;&nbsp;|F| = ' + F_LEN.toFixed(2) + '<br>' +
    'r&#8869; = |r| sin&theta; = ' + (R_LEN * sv).toFixed(2) + '<br>' +
    '|&tau;| = |r||F| sin&theta; = ' + (R_LEN * F_LEN * sv).toFixed(2);
}

/* ── emphasis mode: duplicate vectors stay solid, only support art dims ── */
function setMode(m) {
  mode = m;
  const geo = (m === 'geo');
  consTubeMats.forEach(mt => { mt.opacity = geo ? 1.0 : 0.45; });
  dashMats.forEach(mt => { mt.opacity = geo ? 0.85 : 0.35; });
  skinMat.opacity = geo ? 0.75 : 1.0;
  curlMat.opacity = geo ? 0.8 : 1.0;
  document.getElementById('modeGeo').classList.toggle('active', geo);
  document.getElementById('modeHand').classList.toggle('active', !geo);
  ['th1', 'th2', 'rperp'].forEach(k => {
    if (lbl[k]) lbl[k].div.style.opacity = geo ? '1' : '0.45';
  });
  update();
}

update();

/* ── camera : source axonometric (y nearly horizontal right, x steep down-left) ── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 8, z: 45 },   // world X = figure y, world Z = figure x
  heightFraction: 0.74
});
controls.minPolarAngle = 0.05;
controls.maxPolarAngle = Math.PI * 0.64;

/* ── labels ────────────────────────────────────────────────────────────── */
const VEC = '17px', AX = '13px';
const WBG = 'rgba(255,255,255,0.78)';
addLabel('<i><b>y</b></i>', fv(0, 6.0, 0), { fontSize: AX, offset: [13, 13] });
addLabel('<i><b>z</b></i>', fv(0, 0, 5.0), { fontSize: AX, offset: [-13, -11] });
addLabel('<i><b>x</b></i>', fv(5.0, 0, 0), { fontSize: AX, offset: [-6, 17] });
addLabel('O', ORIGIN, { fontSize: AX, offset: [-16, -8] });
addLabel('<i>P</i>', P, { fontSize: AX, offset: [2, 18] });
addLabel(vec('r'), P.clone().multiplyScalar(0.58), { fontSize: VEC, offset: [2, -19] });

lbl.F = addLabel(vec('F'), P.clone().addScaledVector(Fdir, F_LEN + 0.46),
  { fontSize: VEC, offset: [20, -6] });
lbl.tau = addLabel(vec('&tau;'), P.clone().addScaledVector(UP, 1.9),
  { fontSize: VEC, offset: [19, -4] });
lbl.th1 = addLabel('&theta;', P.clone(), { fontSize: '15px', background: WBG });
lbl.th2 = addLabel('&theta;', P.clone(), { fontSize: '15px', background: WBG });
lbl.rperp = addLabel('<i>r</i><sub>&#8869;</sub>', ORIGIN.clone(),
  { fontSize: '15px', offset: [-8, -12], background: WBG });

lbl.oR = addLabel(vec('r'),
  handGroup.localToWorld(OR_START.clone().add(new THREE.Vector3(OR_LEN + 0.36, 0, 0))),
  { fontSize: VEC, offset: [14, 16] });
lbl.oF = addLabel(vec('F'),
  handGroup.localToWorld(OF_START.clone().add(new THREE.Vector3(F_LEN + 0.44, 0, 0))),
  { fontSize: VEC, offset: [24, -8] });

/* ── interactive explanations ──────────────────────────────────────────── */
registerInteractive(arrR.group, {
  title: 'Position vector r',
  tooltip: 'r: from O to the point of application P',
  body: 'r points from the origin O to P, the point where the force acts. Only the component of r perpendicular to the line of action — the moment arm r⊥ = |r| sin θ — contributes to the torque.'
});
registerInteractive(arrF.group, {
  title: 'Force F',
  tooltip: 'F: applied force at P (drag the θ slider)',
  body: 'F acts at P in the same plane as r. The angle θ between r and F controls the torque: τ = |r||F| sin θ. Sliding θ to 0° or 180° aligns F with the line through O and kills the torque.'
});
registerInteractive(arrTau.group, {
  title: 'Torque τ = r × F',
  tooltip: 'τ: perpendicular to the plane of r and F',
  body: 'τ = r × F stands perpendicular to the plane containing r and F, here along +z. Its length |r||F| sin θ is largest at θ = 90° and zero when r and F are parallel or antiparallel. Orbit the scene to see that it really leaves the r–F plane.'
});
registerInteractive(perpTube.mesh, {
  title: 'Moment arm r⊥',
  tooltip: 'r⊥: perpendicular distance from O to the line of action',
  body: 'r⊥ is the perpendicular dropped from O onto the dashed line of action of F, meeting it at the small right-angle square. Since |τ| = r⊥|F| = |r||F| sin θ, the torque is the force times this moment arm.'
});
registerInteractive(handGroup, {
  title: 'Right-hand rule',
  tooltip: 'Fingers along r, curl toward F, thumb gives τ',
  body: 'Point the fingers of your right hand along r, curl them toward F through the angle θ, and your outstretched thumb points along r × F — here straight up the +z axis, matching the orange τ arrow.'
});

/* ── controls wiring ───────────────────────────────────────────────────── */
const slider = document.getElementById('thetaAngle');
slider.addEventListener('input', () => {
  tween = null; playing = false;
  document.getElementById('btnPlay').textContent = 'Play';
  theta = parseFloat(slider.value);
  update();
});
document.getElementById('modeGeo').addEventListener('click', () => setMode('geo'));
document.getElementById('modeHand').addEventListener('click', () => setMode('hand'));

/* ── guided demo ───────────────────────────────────────────────────────── */
const steps = [
  { title: 'Torque at an oblique angle', narration: 'The force F acts at P, a distance r from the origin. The perpendicular distance r⊥ from O to the line of action sets the moment arm, and τ points straight up along +z.', theta: 35, mode: 'geo' },
  { title: 'Maximum torque at 90°', narration: 'Rotating F until it is perpendicular to r makes r⊥ equal to the full length of r; the orange τ arrow reaches its longest.', theta: 90, mode: 'geo' },
  { title: 'Zero torque when aligned', narration: 'With F along the line of r, the line of action passes through O, r⊥ shrinks to zero and the τ arrow vanishes.', theta: 2, mode: 'geo' },
  { title: 'Right-hand rule fixes the direction', narration: 'Emphasising the hand overlay: the fingers curl from r toward F and the thumb points along +z, matching the orange τ arrow.', theta: 55, mode: 'hand' }
];

function goToStep(i) {
  stepIndex = (i + steps.length) % steps.length;
  const s = steps[stepIndex];
  setMode(s.mode);
  tween = { from: theta, to: s.theta, t: 0 };
  document.getElementById('stepTitle').textContent = (stepIndex + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narration;
  dwell = 0;
}
document.getElementById('btnPrev').addEventListener('click', () => { playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIndex - 1); });
document.getElementById('btnNext').addEventListener('click', () => { playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIndex + 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.textContent = playing ? 'Pause' : 'Play';
  if (playing) goToStep(stepIndex);
});
goToStep(0);
setMode('geo');

/* ── own animation loop (tween + pulse highlight) ──────────────────────── */
const C_BLACK = new THREE.Color(BLACK), C_ORANGE = new THREE.Color(ORANGE),
  C_GLOW = new THREE.Color(0xFFD27A);
let _t0 = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - _t0) / 1000); _t0 = now;

  if (tween) {
    tween.t = Math.min(1, tween.t + dt / 0.9);
    const k = tween.t * tween.t * (3 - 2 * tween.t);
    theta = tween.from + (tween.to - tween.from) * k;
    slider.value = theta.toFixed(0);
    update();
    if (tween.t >= 1) { theta = tween.to; tween = null; }
  } else if (playing) {
    dwell += dt;
    if (dwell > 3.2) goToStep(stepIndex + 1);
  }

  if (mode === 'hand') {
    const k = 0.5 + 0.5 * Math.sin(now * 0.004);
    curlMat.color.copy(C_BLACK).lerp(C_ORANGE, 0.75 * k);
    arrTau.mat.color.copy(C_ORANGE).lerp(C_GLOW, k);
  } else {
    curlMat.color.copy(C_BLACK);
    arrTau.mat.color.copy(C_ORANGE);
  }
}
requestAnimationFrame(tick);
